//
//   - paramsArray: of the decompression operation for which the error returned by this function pertains to. If
//   - count: The number of entries in
//   - flags: Must be 0
//
// Wraps cuMemBatchDecompressAsync.
func (s Stream) MemBatchDecompressAsync(paramsArray *MemDecompressParams, count uint, flags uint32) (uint, error) {
	return memBatchDecompressAsync(paramsArray, count, flags, s)
}

// MemDiscardAndPrefetchBatchAsync Performs a batch of memory discards and prefetches asynchronously.
//
// Performs a batch of memory discards followed by prefetches. The batch as a whole executes in stream order but operations within a batch are not guaranteed to execute in any specific order. All devices in the system must have a non-zero value for the device attribute [DevAttrConcurrentManagedAccess] otherwise the API will return an error. Calling [Stream.MemDiscardAndPrefetchBatchAsync] is semantically equivalent to calling [Stream.MemDiscardBatchAsync] followed by [Stream.MemPrefetchBatchAsync], but is more optimal. For more details on what discarding and prefetching imply, please refer to [Stream.MemDiscardBatchAsync] and [Stream.MemPrefetchBatchAsync] respectively. Note that any reads, writes or prefetches to any part of the memory range that occur simultaneously with this combined discard+prefetch operation result in undefined behavior. Performs memory discard and prefetch on address ranges specified in dptrs and sizes. Both arrays must be of the same length as specified by count. Each memory range specified must refer to managed memory allocated via [MemAllocManaged] or declared via __managed__ variables or it may also refer to system-allocated memory when all devices have a non-zero value for [DevAttrPageableMemoryAccess]. Every operation in the batch has to be associated with a valid location to prefetch the address range to and specified in the prefetchLocs array. Each entry in this array can apply to more than one operation. This can be done by specifying in the prefetchLocIdxs array, the index of the first operation that the corresponding entry in the prefetchLocs array applies to. Both prefetchLocs and prefetchLocIdxs must be of the same length as specified by numPrefetchLocs. For example, if a batch has 10 operations listed in dptrs/sizes, the first 6 of which are to be prefetched to one location and the remaining 4 are to be prefetched to another, then numPrefetchLocs will be 2, prefetchLocIdxs will be {0, 6} and prefetchLocs will contain the two set of locations. Note the first entry in prefetchLocIdxs must always be 0. Also, each entry must be greater than the previous entry and the last entry should be less than count. Furthermore, numPrefetchLocs must be lesser than or equal to count.
//
//   - dptrs: Array of pointers to be discarded
//   - sizes: Array of sizes for memory discard operations
//   - count: Size of dptrs and sizes arrays
//   - prefetchLocs: Array of locations to prefetch to
//   - prefetchLocIdxs: Array of indices to specify which operands each entry in the prefetchLocs array applies to. The locations specified in prefetchLocsk will be applied to operations starting from prefetchLocIdxsk through prefetchLocIdxs [k+1] - 1. Also prefetchLocs [numPrefetchLocs - 1] will apply to copies starting from prefetchLocIdxs [numPrefetchLocs - 1] through count - 1
//   - numPrefetchLocs: Size of prefetchLocs and prefetchLocIdxs arrays
//   - flags: Flags reserved for future use. Must be zero
//
// Wraps cuMemDiscardAndPrefetchBatchAsync.
func (s Stream) MemDiscardAndPrefetchBatchAsync(dptrs *DevicePtr, sizes *uint, count uint, prefetchLocs *MemLocation, prefetchLocIdxs *uint, numPrefetchLocs uint, flags uint64) error {
	return memDiscardAndPrefetchBatchAsync(dptrs, sizes, count, prefetchLocs, prefetchLocIdxs, numPrefetchLocs, flags, s)
}

// MemDiscardBatchAsync Performs a batch of memory discards asynchronously.
//
// Performs a batch of memory discards. The batch as a whole executes in stream order but operations within a batch are not guaranteed to execute in any specific order. All devices in the system must have a non-zero value for the device attribute [DevAttrConcurrentManagedAccess] otherwise the API will return an error. Discarding a memory range informs the driver that the contents of that range are no longer useful. Discarding memory ranges allows the driver to optimize certain data migrations and can also help reduce memory pressure. This operation can be undone on any part of the range by either writing to it or prefetching it via [DevicePtr.MemPrefetchAsync] or [Stream.MemPrefetchBatchAsync]. Reading from a discarded range, without a subsequent write or prefetch to that part of the range, will return an indeterminate value. Note that any reads, writes or prefetches to any part of the memory range that occur simultaneously with the discard operation result in undefined behavior. Performs memory discard on address ranges specified in dptrs and sizes. Both arrays must be of the same length as specified by count. Each memory range specified must refer to managed memory allocated via [MemAllocManaged] or declared via __managed__ variables or it may also refer to system-allocated memory when all devices have a non-zero value for [DevAttrPageableMemoryAccess].
//
//   - dptrs: Array of pointers to be discarded
//   - sizes: Array of sizes for memory discard operations
//   - count: Size of dptrs and sizes arrays
//   - flags: Flags reserved for future use. Must be zero
//
// Wraps cuMemDiscardBatchAsync.
func (s Stream) MemDiscardBatchAsync(dptrs *DevicePtr, sizes *uint, count uint, flags uint64) error {
	return memDiscardBatchAsync(dptrs, sizes, count, flags, s)
}

// MemMapArrayAsync Maps or unmaps subregions of sparse CUDA arrays and sparse CUDA mipmapped arrays.
//
// Performs map or unmap operations on subregions of sparse CUDA arrays and sparse CUDA mipmapped arrays. Each operation is specified by a [ArrayMapInfo] entry in the mapInfoList array of size count. The structure [ArrayMapInfo] is defined as follow: where [ArrayMapInfo].resourceType specifies the type of resource to be operated on. If [ArrayMapInfo].resourceType is set to [Resourcetype].[ResourceTypeArray] then [ArrayMapInfo].resourcearray must be set to a valid sparse CUDA array handle. The CUDA array must be either a 2D, 2D layered or 3D CUDA array and must have been allocated using [NewArray] or [NewArray3D] with the flag CUDA_ARRAY3D_SPARSE or CUDA_ARRAY3D_DEFERRED_MAPPING. For CUDA arrays obtained using [MipmappedArray.GetLevel], [ErrInvalidValue] will be returned. If [ArrayMapInfo].resourceType is set to [Resourcetype].[ResourceTypeMipmappedArray] then [ArrayMapInfo].resourcemipmap must be set to a valid sparse CUDA mipmapped array handle. The CUDA mipmapped array must be either a 2D, 2D layered or 3D CUDA mipmapped array and must have been allocated using [NewMipmappedArray] with the flag CUDA_ARRAY3D_SPARSE or CUDA_ARRAY3D_DEFERRED_MAPPING. [ArrayMapInfo].subresourceType specifies the type of subresource within the resource. CUarraySparseSubresourceType_enum is defined as: where [ArraySparseSubresourceType].[ArraySparseSubresourceTypeSparseLevel] indicates a sparse-miplevel which spans at least one tile in every dimension. The remaining miplevels which are too small to span at least one tile in any dimension constitute the mip tail region as indicated by [ArraySparseSubresourceType].[ArraySparseSubresourceTypeMiptail] subresource type. If [ArrayMapInfo].subresourceType is set to [ArraySparseSubresourceType].[ArraySparseSubresourceTypeSparseLevel] then [ArrayMapInfo].subresourcesparseLevel struct must contain valid array subregion offsets and extents. The [ArrayMapInfo].subresourcesparseLevel.offsetX, [ArrayMapInfo].subresourcesparseLevel.offsetY and [ArrayMapInfo].subresourcesparseLevel.offsetZ must specify valid X, Y and Z offsets respectively. The [ArrayMapInfo].subresourcesparseLevel.extentWidth, [ArrayMapInfo].subresourcesparseLevel.extentHeight and [ArrayMapInfo].subresourcesparseLevel.extentDepth must specify valid width, height and depth extents respectively. These offsets and extents must be aligned to the corresponding tile dimension. For CUDA mipmapped arrays [ArrayMapInfo].subresourcesparseLevel.level must specify a valid mip level index. Otherwise, must be zero. For layered CUDA arrays and layered CUDA mipmapped arrays [ArrayMapInfo].subresourcesparseLevel.layer must specify a valid layer index. Otherwise, must be zero. [ArrayMapInfo].subresourcesparseLevel.offsetZ must be zero and [ArrayMapInfo].subresourcesparseLevel.extentDepth must be set to 1 for 2D and 2D layered CUDA arrays and CUDA mipmapped arrays. Tile extents can be obtained by calling [Array.GetSparseProperties] and [MipmappedArray.GetSparseProperties] If [ArrayMapInfo].subresourceType is set to [ArraySparseSubresourceType].[ArraySparseSubresourceTypeMiptail] then [ArrayMapInfo].subresourcemiptail struct must contain valid mip tail offset in [ArrayMapInfo].subresourcemiptail.offset and size in [ArrayMapInfo].subresourcemiptail.size. Both, mip tail offset and mip tail size must be aligned to the tile size. For layered CUDA mipmapped arrays which don't have the flag CU_ARRAY_SPARSE_PROPERTIES_SINGLE_MIPTAIL set in [ArraySparseProperties].flags as returned by [MipmappedArray.GetSparseProperties], [ArrayMapInfo].subresourcemiptail.layer must specify a valid layer index. Otherwise, must be zero. If [ArrayMapInfo].resourcearray or [ArrayMapInfo].resourcemipmap was created with CUDA_ARRAY3D_DEFERRED_MAPPING flag set the [ArrayMapInfo].subresourceType and the contents of [ArrayMapInfo].subresource will be ignored. [ArrayMapInfo].memOperationType specifies the type of operation. [MemOperationType] is defined as: If [ArrayMapInfo].memOperationType is set to [MemOperationType].[MemOperationTypeMap] then the subresource will be mapped onto the tile pool memory specified by [ArrayMapInfo].memHandle at offset [ArrayMapInfo].offset. The tile pool allocation has to be created by specifying the CU_MEM_CREATE_USAGE_TILE_POOL flag when calling [MemCreate]. Also, [ArrayMapInfo].memHandleType must be set to [MemHandleType].[MemHandleTypeGeneric]. If [ArrayMapInfo].memOperationType is set to [MemOperationType].[MemOperationTypeUnmap] then an unmapping operation is performed. [ArrayMapInfo].memHandle must be NULL. [ArrayMapInfo].deviceBitMask specifies the list of devices that must map or unmap physical memory. Currently, this mask must have exactly one bit set, and the corresponding device must match the device associated with the stream. If [ArrayMapInfo].memOperationType is set to [MemOperationType].[MemOperationTypeMap], the device must also match the device associated with the tile pool memory allocation as specified by [ArrayMapInfo].memHandle. [ArrayMapInfo].flags and [ArrayMapInfo].reserved[] are unused and must be set to zero. See also: [NewMipmappedArray], [NewArray], [NewArray3D], [MemCreate], [Array.GetSparseProperties], [MipmappedArray.GetSparseProperties]
//
//   - mapInfoList (in): List of [ArrayMapInfo]
//   - count (in): Count of [ArrayMapInfo] in mapInfoList
//
// Wraps cuMemMapArrayAsync.
func (s Stream) MemMapArrayAsync(mapInfoList *ArrayMapInfo, count uint32) error {
	return memMapArrayAsync(mapInfoList, count, s)
}

// MemPrefetchBatchAsync Performs a batch of memory prefetches asynchronously.
//
// Performs a batch of memory prefetches. The batch as a whole executes in stream order but operations within a batch are not guaranteed to execute in any specific order. All devices in the system must have a non-zero value for the device attribute [DevAttrConcurrentManagedAccess] otherwise the API will return an error. The semantics of the individual prefetch operations are as described in [DevicePtr.MemPrefetchAsync]. Performs memory prefetch on address ranges specified in dptrs and sizes. Both arrays must be of the same length as specified by count. Each memory range specified must refer to managed memory allocated via [MemAllocManaged] or declared via __managed__ variables or it may also refer to system-allocated memory when all devices have a non-zero value for [DevAttrPageableMemoryAccess]. The prefetch location for every operation in the batch is specified in the prefetchLocs array. Each entry in this array can apply to more than one operation. This can be done by specifying in the prefetchLocIdxs array, the index of the first prefetch operation that the corresponding entry in the prefetchLocs array applies to. Both prefetchLocs and prefetchLocIdxs must be of the same length as specified by numPrefetchLocs. For example, if a batch has 10 prefetches listed in dptrs/sizes, the first 4 of which are to be prefetched to one location and the remaining 6 are to be prefetched to another, then numPrefetchLocs will be 2, prefetchLocIdxs will be {0, 4} and prefetchLocs will contain the two locations. Note the first entry in prefetchLocIdxs must always be 0. Also, each entry must be greater than the previous entry and the last entry should be less than count. Furthermore, numPrefetchLocs must be lesser than or equal to count.
//
//   - dptrs: Array of pointers to be prefetched
//   - sizes: Array of sizes for memory prefetch operations
//   - count: Size of dptrs and sizes arrays
//   - prefetchLocs: Array of locations to prefetch to
//   - prefetchLocIdxs: Array of indices to specify which operands each entry in the prefetchLocs array applies to. The locations specified in prefetchLocsk will be applied to copies starting from prefetchLocIdxsk through prefetchLocIdxs [k+1] - 1. Also prefetchLocs [numPrefetchLocs - 1] will apply to prefetches starting from prefetchLocIdxs [numPrefetchLocs - 1] through count - 1
//   - numPrefetchLocs: Size of prefetchLocs and prefetchLocIdxs arrays
//   - flags: Flags reserved for future use. Must be zero
//
// Wraps cuMemPrefetchBatchAsync.
func (s Stream) MemPrefetchBatchAsync(dptrs *DevicePtr, sizes *uint, count uint, prefetchLocs *MemLocation, prefetchLocIdxs *uint, numPrefetchLocs uint, flags uint64) error {
	return memPrefetchBatchAsync(dptrs, sizes, count, prefetchLocs, prefetchLocIdxs, numPrefetchLocs, flags, s)
}

